import{_ as r,C as a,o as s,c as n,j as t,a as i,E as c,a6 as d}from"./chunks/framework.CCKCzdWs.js";const h="/screenshots/picker-record.png",b=JSON.parse(`{"title":"Record actions","description":"Record clicks and fills across a site's pages with Piwi Picker into a runnable Playwright spec, paused, titled and replayed before you export it.","frontmatter":{"title":"Record actions","description":"Record clicks and fills across a site's pages with Piwi Picker into a runnable Playwright spec, paused, titled and replayed before you export it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/record-actions.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/record-actions.html"}],["meta",{"property":"og:title","content":"Record actions | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Record clicks and fills across a site's pages with Piwi Picker into a runnable Playwright spec, paused, titled and replayed before you export it."}]]},"headers":[],"relativePath":"features/record-actions.md","filePath":"features/record-actions.md","lastUpdated":1793443978000}`),l={name:"features/record-actions.md"};function p(g,e,f,u,m,w){const o=a("Needs");return s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"record-actions",tabindex:"-1"},[i("Record actions "),t("a",{class:"header-anchor",href:"#record-actions","aria-label":'Permalink to "Record actions"'},"​")],-1)),c(o,{extension:""}),e[1]||(e[1]=d('<p><strong>Record actions</strong> asks for access to the site you are on, then captures clicks, fills, checks, choices, drags, the names of chosen files (never their content), the keys that submit, close or move through a list, a click on what a hover shows, and the browser&#39;s <strong>Back</strong>, <strong>Forward</strong> and reload as a step to the page they reach, across pages. Each element is recorded with up to five locators that find it alone, ranked, so a replay has others to try when one no longer holds. <strong>Check an element</strong> and <strong>Check the address</strong> add an <code>expect(…)</code> of what the page shows now. <strong>Pause</strong> stops capturing without ending the recording, on every page and tab of it, so signing in or closing a banner stays out of the spec, until <strong>Resume</strong>. The bar sits in a corner of the page; when it covers something you need to click, its four-arrow button (<strong>Move this bar to another corner</strong>) moves it to the next corner, where it stays on every page. <strong>Stop</strong> opens the review: the <strong>Test title</strong>, filled with the first page&#39;s own title (or, left empty, the first step in words), names the spec&#39;s test and the steps file; <strong>Copy as TypeScript</strong> for a runnable spec that waits for each page it opens, <strong>Download steps</strong> for a <a href="/reference/steps-format.html">steps file</a> to share or render with <a href="/reference/cli.html#codegen"><code>piwi codegen</code></a>, <a href="./editor-recording.html#send-from-piwi-picker"><strong>Send to editor</strong></a>, <a href="./replay-a-bug-report.html"><strong>Replay</strong></a> to play the steps again in the tab and see that each still finds its element, or <strong>Discard</strong>. Passwords are never captured, nor a card number, its security code or a one-time code in a field whose <code>autocomplete</code> names it: the spec reads them from <code>process.env</code>.</p><figure><img src="'+h+'" alt="The review panel after a recording: seven steps, Copy as TypeScript"><figcaption>The review after Stop: every step, the spec one click away.</figcaption></figure><h2 id="matching-functions" tabindex="-1">Matching functions <a class="header-anchor" href="#matching-functions" aria-label="Permalink to &quot;Matching functions&quot;">​</a></h2><p>With a connection, the recorder loads the <a href="./test-functions.html">function catalog</a> of the project mapped to the page and ranks, while you record, the functions the steps look like. On export, a complete match becomes a call to your function. No AI: it scores your registered functions&#39; DOM patterns.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./report-a-bug.html">Report a bug</a>: the same recording, with what the page should show and the evidence</li><li><a href="./replay-a-bug-report.html">Replay a bug report</a>: play recorded steps again in a tab</li><li><a href="/reference/steps-format.html">Steps file</a>: the format <strong>Download steps</strong> writes</li><li><a href="./editor-recording.html#send-from-piwi-picker">Send to editor</a>: the spec inserted in VS Code or a JetBrains IDE</li><li><a href="./extension.html">Browser extension</a>: the other tools, the permissions and the limits</li></ul>',6))])}const k=r(l,[["render",p]]);export{b as __pageData,k as default};
